3	import net.officefloor.plugin.variable.Val;
4	import org.slf4j.Logger;
5	import org.slf4j.LoggerFactory;
6	import org.springframework.samples.petclinic.mapper.OwnerMapper;
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Emits an audit trail entry for a successful owner create in {@code POST /api/owners}.
11	 * Publishes a single line to the dedicated {@code AUDIT} logger carrying the persisted
12	 * owner's id, its assigned {@code customerCode}, its {@code registrationDate}, its assigned
13	 * {@code membershipLevel} and its derived {@code membershipNumber}. Runs after {@link SaveOwner}
14	 * so the generated id is available, and before the response is sent.
15	 */
16	public class AuditOwnerCreated {
17	
18	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
19	
20	    public void service(@Val Owner owner, OwnerMapper ownerMapper) {
21	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
22	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
23	                owner.getMembershipLevel(), ownerMapper.membershipNumber(owner));
24	    }
25	}
