1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity;
9	import org.springframework.samples.petclinic.rest.function.owner.OwnerTelephone;
10	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
13	import org.springframework.samples.petclinic.util.AgeBand;
14	import org.springframework.samples.petclinic.util.CustomerCode;
15	import org.springframework.samples.petclinic.util.FiscalYear;
16	import org.springframework.samples.petclinic.util.Luhn;
17	import org.springframework.samples.petclinic.util.OwnerRegion;
18	import org.springframework.samples.petclinic.util.RegionTimezone;
19	
20	import java.util.Collection;
21	import java.util.List;
22	
23	/**
24	 * Maps Owner & OwnerDto using Mapstruct
25	 */
26	@Mapper(uses = PetMapper.class)
27	public interface OwnerMapper {
28	
29	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
30	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
31	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
32	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
33	    @Mapping(target = "initials", expression = "java(initials(owner))")
34	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
35	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
36	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
37	    @Mapping(target = "locality", expression = "java(locality(owner))")
38	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
39	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
40	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
41	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
42	    OwnerDto toOwnerDto(Owner owner);
43	
44	    /** The owner's canonical relative URL, '/api/owners/' followed by its id. */
45	    default String selfLink(Owner owner) {
46	        return "/api/owners/" + owner.getId();
47	    }
48	
49	    /** The owner's stored E.164 telephone formatted for people to read (country code, space,
50	     *  national digits grouped in threes), or null when it is not a recognised E.164 number.
51	     *  See {@link OwnerTelephone#toDisplay}. */
52	    default String telephoneDisplay(Owner owner) {
53	        return OwnerTelephone.toDisplay(owner.getTelephone()).orElse(null);
54	    }
55	
56	    /** The owner's name formatted as 'LastName, FirstName' from the stored names. */
57	    default String displayName(Owner owner) {
58	        return owner.getLastName() + ", " + owner.getFirstName();
59	    }
60	
61	    /** The owner's salutation: the courtesy title followed by a space and the lastName
62	     *  (e.g. 'DR Franklin'), or just the lastName when no title was supplied. */
63	    default String salutation(Owner owner) {
64	        String title = owner.getTitle();
65	        return title == null || title.isBlank()
66	                ? owner.getLastName()
67	                : title + " " + owner.getLastName();
68	    }
69	
70	    /** The upper-cased first letters of firstName and lastName, dot-separated with a
71	     *  trailing dot, e.g. 'J.S.'. */
72	    default String initials(Owner owner) {
73	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
74	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
75	    }
76	
77	    /** The membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last two digits of
78	     *  the registrationDate's fiscal year (see {@link FiscalYear}, e.g. 'NSW-1A2B3C4D-M27'). Null
79	     *  when either source field is absent. */
80	    default String membershipNumber(Owner owner) {
81	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
82	            return null;
83	        }
84	        return String.format("%s-M%02d", owner.getCustomerCode(), FiscalYear.of(owner.getRegistrationDate()) % 100);
85	    }
86	
87	    /** The registrationDate's fiscal year as 'FY&lt;YY&gt;' (see {@link FiscalYear}, e.g. 'FY27').
88	     *  Null when the registrationDate is absent. */
89	    default String fiscalYear(Owner owner) {
90	        return owner.getRegistrationDate() == null ? null : FiscalYear.label(owner.getRegistrationDate());
91	    }
92	
93	    /** The Luhn check digit over the digits of the customerCode. Null when the customerCode
94	     *  is absent. */
95	    default Integer checkDigit(Owner owner) {
96	        return owner.getCustomerCode() == null ? null : Luhn.checkDigit(owner.getCustomerCode());
97	    }
98	
99	    /** The owner's locality: the REGION segment of its customerCode, which is the canonical region
100	     *  the code was built from. Falls back to deriving the region straight from the postcode and
101	     *  city when the customerCode is absent (so an owner without one still resolves a locality). */
102	    default String locality(Owner owner) {
103	        return owner.getCustomerCode() != null
104	                ? CustomerCode.region(owner.getCustomerCode())
105	                : OwnerRegion.of(owner.getPostcode(), owner.getCity());
106	    }
107	
108	    /** The owner's timezone: the IANA name from the fixed region-to-timezone table
109	     *  (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne, QLD-&gt;Australia/Brisbane), keyed
110	     *  off the owner's {@link #locality locality}. Null when the region has no mapped timezone. */
111	    default String timezone(Owner owner) {
112	        return RegionTimezone.of(locality(owner));
113	    }
114	
115	    /** The owner's preferred contact method: 'EMAIL' when an email address is present,
116	     *  otherwise 'PHONE'. */
117	    default String contactPreference(Owner owner) {
118	        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
119	    }
120	
121	    /** The owner's derived duplicate-detection identity key: the SHA-256 hex of the normalized
122	     *  telephone, lower-cased email and soundex(lastName) joined by '|'. See {@link OwnerIdentity#key}. */
123	    default String identityKey(Owner owner) {
124	        return OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getLastName());
125	    }
126	
127	    /** The owner's age band derived from its birthDate against its registrationDate, or null when
128	     *  either date is absent. See {@link AgeBand}. */
129	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
130	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
131	            return null;
132	        }
133	        return OwnerDto.AgeBandEnum.fromValue(AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()));
134	    }
135	
136	    Owner toOwner(OwnerDto ownerDto);
137	
138	    @Mapping(target = "id", ignore = true)
139	    @Mapping(target = "pets", ignore = true)
140	    Owner toOwner(OwnerFieldsDto ownerDto);
141	
142	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
143	
144	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
145	
146	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
147	        OwnerPageDto ownerPageDto = new OwnerPageDto();
148	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
149	        ownerPageDto.setPage(ownerPage.getNumber());
150	        ownerPageDto.setSize(ownerPage.getSize());
151	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
152	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
153	        return ownerPageDto;
154	    }
155	}
