1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Runs in {@code POST /api/owners} after {@link AssignOwnerMembershipPoints} has recorded the
8	 * owner's membership points and before it is saved, within the create transaction. Records on the
9	 * built owner its numeric membership level, derived solely from those points: level 1 for 0-1
10	 * points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
11	 */
12	public class AssignOwnerMembershipLevel {
13	
14	    public void service(@Val Owner owner) {
15	        owner.setMembershipLevel(levelFor(owner.getMembershipPoints()));
16	    }
17	
18	    /** Maps membership points onto the membership level band that contains them. */
19	    private static int levelFor(int points) {
20	        if (points >= 6) {
21	            return 4;
22	        }
23	        if (points >= 4) {
24	            return 3;
25	        }
26	        if (points >= 2) {
27	            return 2;
28	        }
29	        return 1;
30	    }
31	}
