1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.util.FiscalYear;
8	
9	/**
10	 * Runs in {@code POST /api/owners} after the owner's household size and namesake count have been
11	 * recorded and before it is saved, within the create transaction. Records on the built owner its
12	 * numeric membership points: starting at 0, it gains 2 when an email is present, 1 more when
13	 * {@link Owner#getNamesakeCount() namesakeCount} is 0, 2 for a household of
14	 * {@link #LARGE_HOUSEHOLD_MIN} or more members, and 3 when the owner's tenure exceeds
15	 * {@link #TENURE_FISCAL_YEARS_FOR_BONUS} elapsed fiscal year(s). Because a newly registered owner
16	 * has zero tenure, a new owner never earns the tenure points. Reads the resolved (weekend-adjusted) registration date
17	 * published by {@link ResolveOwnerRegistrationDate} — the owner is not stamped with it until
18	 * {@link ApplyOwnerRegistrationDate}, which runs later. {@link AssignOwnerMembershipLevel} maps the
19	 * points recorded here onto the membership level.
20	 */
21	public class AssignOwnerMembershipPoints {
22	
23	    /** Points earned when the owner has an email address. */
24	    private static final int EMAIL_POINTS = 2;
25	
26	    /** Points earned when no existing owner shared the owner's name at creation. */
27	    private static final int UNIQUE_NAME_POINTS = 1;
28	
29	    /** Points earned when the owner belongs to a household of {@link #LARGE_HOUSEHOLD_MIN}+. */
30	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
31	
32	    /** Smallest household size that earns {@link #LARGE_HOUSEHOLD_POINTS}. */
33	    private static final int LARGE_HOUSEHOLD_MIN = 3;
34	
35	    /** Points earned when tenure exceeds {@link #TENURE_FISCAL_YEARS_FOR_BONUS} elapsed fiscal year(s). */
36	    private static final int LONG_TENURE_POINTS = 3;
37	
38	    /** Elapsed fiscal years an owner's tenure must exceed to earn {@link #LONG_TENURE_POINTS}. */
39	    private static final long TENURE_FISCAL_YEARS_FOR_BONUS = 1;
40	
41	    public void service(@Val Owner owner, @Val LocalDate registrationDate) {
42	        int points = 0;
43	        if (hasEmail(owner)) {
44	            points += EMAIL_POINTS;
45	        }
46	        if (hasUniqueName(owner)) {
47	            points += UNIQUE_NAME_POINTS;
48	        }
49	        if (hasLargeHousehold(owner)) {
50	            points += LARGE_HOUSEHOLD_POINTS;
51	        }
52	        if (tenureFiscalYears(registrationDate) > TENURE_FISCAL_YEARS_FOR_BONUS) {
53	            points += LONG_TENURE_POINTS;
54	        }
55	        owner.setMembershipPoints(points);
56	    }
57	
58	    private static boolean hasEmail(Owner owner) {
59	        return owner.getEmail() != null && !owner.getEmail().isEmpty();
60	    }
61	
62	    private static boolean hasUniqueName(Owner owner) {
63	        return owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
64	    }
65	
66	    private static boolean hasLargeHousehold(Owner owner) {
67	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= LARGE_HOUSEHOLD_MIN;
68	    }
69	
70	    /** Fiscal years the owner has been registered as of today; zero for a new owner. */
71	    private static long tenureFiscalYears(LocalDate registrationDate) {
72	        return FiscalYear.elapsed(registrationDate, LocalDate.now());
73	    }
74	}
