1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Runs in {@code POST /api/owners} after {@link AssignOwnerMembershipLevel} has derived the owner's
9	 * membership level from its points and before it is saved, within the create transaction. Caps that
10	 * level at one above the current maximum membership level among the owner's existing household
11	 * members (those already sharing its {@link Owner#getHouseholdId() household id}), so a new member
12	 * cannot leap more than one level beyond the household. With no existing household member no cap
13	 * applies. Because the new owner has not yet been persisted, {@link OwnerRepository#findAll()}
14	 * returns only the existing members, so the owner is never capped against itself.
15	 */
16	public class CapOwnerMembershipLevel {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String householdId = owner.getHouseholdId();
20	        ownerRepository.findAll().stream()
21	                .filter(existing -> householdId.equals(existing.getHouseholdId()))
22	                .map(Owner::getMembershipLevel)
23	                .filter(level -> level != null)
24	                .mapToInt(Integer::intValue)
25	                .max()
26	                .ifPresent(maxLevel -> owner.setMembershipLevel(
27	                        Math.min(owner.getMembershipLevel(), maxLevel + 1)));
28	    }
29	}
