1	package org.springframework.samples.petclinic.util;
2	
3	import java.util.Locale;
4	import java.util.Set;
5	
6	/**
7	 * The owner's customer code, {@code '<REGION>-<HASH8>'}: the owner's {@link OwnerRegion region}
8	 * joined to an 8-character hash that identifies the person. HASH8 is the first 8 upper-case hex
9	 * characters of {@code SHA-256(normalizedTelephone + lastName)}, so the same person (same
10	 * normalized telephone and last name) always resolves to the same code without any sequence
11	 * number (e.g. {@code 'NSW-1A2B3C4D'}).
12	 */
13	public final class CustomerCode {
14	
15	    private static final String SEPARATOR = "-";
16	
17	    /** Number of leading hex characters of the digest kept as HASH8. */
18	    private static final int HASH_LENGTH = 8;
19	
20	    private CustomerCode() {
21	    }
22	
23	    /**
24	     * The customer code for the given {@code region} and person, hashing the person's
25	     * {@code normalizedTelephone} and {@code lastName}.
26	     */
27	    public static String of(String region, String normalizedTelephone, String lastName) {
28	        return region + SEPARATOR + hash8(orEmpty(normalizedTelephone) + orEmpty(lastName));
29	    }
30	
31	    /**
32	     * De-duplicates {@code customerCode} against the codes already {@code taken}: if it is unused it
33	     * is returned unchanged, otherwise {@code '-<n>'} is appended with the smallest {@code n >= 2}
34	     * that yields a code not already taken (e.g. {@code 'NSW-1A2B3C4D'} → {@code 'NSW-1A2B3C4D-2'}).
35	     */
36	    public static String deduplicate(String customerCode, Set<String> taken) {
37	        if (!taken.contains(customerCode)) {
38	            return customerCode;
39	        }
40	        for (int n = 2; ; n++) {
41	            String candidate = customerCode + SEPARATOR + n;
42	            if (!taken.contains(candidate)) {
43	                return candidate;
44	            }
45	        }
46	    }
47	
48	    /** The REGION segment of a customer code (the text before the first {@code '-'}). */
49	    public static String region(String customerCode) {
50	        int separator = customerCode.indexOf(SEPARATOR);
51	        return separator < 0 ? customerCode : customerCode.substring(0, separator);
52	    }
53	
54	    private static String hash8(String source) {
55	        return Sha256.hex(source).substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
56	    }
57	
58	    private static String orEmpty(String value) {
59	        return value == null ? "" : value;
60	    }
61	}
